            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Przyrzekam na kobiety stałość niewzruszoną, nienawidzić ród męski, nigdy nie być żoną.", Author = "Aleksander Fredro" },
