            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Razu jednego… kiedy w malignie zasnąłem, Wpadł mi palec w kałamarz… i pisać zacząłem.", Author = "Aleksander Fredro" },
