            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Nie ma większej radości dla głupiego, jak znaleźć głupszego od siebie.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Bo ja rzadko kiedy myślę, alem za to chyża w dziele.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Jeśli nie chcesz mojej zguby, krrrokodyla daj mi luby.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Niech się dzieje wola nieba, z nią się zawsze zgadzać trzeba.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Ale teraz to się staje, że od kury mędrsze jaje.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Ale miłość, choć się śmieje, Nie nakarmi, nie ogrzeje.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Człowiek rozsądny unika tajemnic jak powietrza.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Czy miłość musi być ślepa? Niekoniecznie! Wystarczy, że zakochany umie przymykać oczy.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "I kura ma skrzydła jak orzeł, ale cóż z tego?", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Ludzie ze szkodą gonią za modą.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Mieć rozsądek dla siebie – jest już bardzo wiele.", Author = "Aleksander Fredro" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Nie bardzo prawda miła i od przyjaciela.", Author = "Aleksander Fredro" },
