            new Quote { Id = "https://pl.wikiquote.org/wiki/Aleksander_Fredro", Text = "Rozwaga w miłości zdaje się być niepotrzebna, bo zawsze na końcu robi się tak, jakby się nic nie rozważało.", Author = "Aleksander Fredro" },
